import 'package:flutter/material.dart';
import '../../auth/auth_service.dart';
import '../../operaciones/operaciones_service.dart';
import '../../theme/app_colors.dart';
import '../../widgets/app_feedback.dart';
import '../../widgets/field_group.dart';
import 'turno_bombeo_service.dart';
import 'turno_bombeo_widgets.dart';

/// Opens the operator's turno de bombeo. The bomba comes from
/// [TurnoBombeoService.miBomba]; the folio is generated by the backend.
/// Pops `true` once opened.
class AbrirTurnoScreen extends StatefulWidget {
  const AbrirTurnoScreen({super.key});

  @override
  State<AbrirTurnoScreen> createState() => _AbrirTurnoScreenState();
}

class _AbrirTurnoScreenState extends State<AbrirTurnoScreen> {
  final _formKey = GlobalKey<FormState>();
  final _horometro = TextEditingController();
  final _auxiliar = TextEditingController();
  final _cliente = TextEditingController();
  final _direccion = TextEditingController();
  final _entreCalles = TextEditingController();
  final _telefono = TextEditingController();
  final _solicitadoPor = TextEditingController();
  final _observaciones = TextEditingController();

  late final Future<BombaPropia?> _bombaFuture = TurnoBombeoService.miBomba();
  bool _enviando = false;

  @override
  void dispose() {
    for (final c in [
      _horometro,
      _auxiliar,
      _cliente,
      _direccion,
      _entreCalles,
      _telefono,
      _solicitadoPor,
      _observaciones,
    ]) {
      c.dispose();
    }
    super.dispose();
  }

  String _hoy() {
    final d = DateTime.now();
    return '${d.year.toString().padLeft(4, '0')}-${d.month.toString().padLeft(2, '0')}-${d.day.toString().padLeft(2, '0')}';
  }

  Future<void> _enviar(BombaPropia bomba) async {
    if (!_formKey.currentState!.validate()) return;
    final idEmpleado = AuthService.idEmpleado;
    if (idEmpleado == null) {
      AppSnack.error(
        context,
        'No se encontró tu número de empleado. Vuelve a iniciar sesión.',
      );
      return;
    }
    setState(() => _enviando = true);
    try {
      final turno = await OperacionesService.abrirTurnoBombeo(
        vehiculoBombaId: bomba.id,
        conductorBombaId: idEmpleado,
        fecha: _hoy(),
        horometroInicio: leerNumero(_horometro),
        auxiliarNombre: leerTexto(_auxiliar),
        clienteNombre: leerTexto(_cliente),
        direccionObra: leerTexto(_direccion),
        entreCalles: leerTexto(_entreCalles),
        telefono: leerTexto(_telefono),
        solicitadoPor: leerTexto(_solicitadoPor),
        observaciones: leerTexto(_observaciones),
      );
      if (!mounted) return;
      AppSnack.success(context, 'Turno ${turno.folio} abierto');
      Navigator.of(context).pop(true);
    } on AuthException catch (e) {
      // The 409 "ya hay un turno abierto para esta bomba" comes back with
      // a readable Spanish message, shown as-is.
      if (mounted) AppSnack.error(context, e.message);
    } catch (_) {
      if (mounted) AppSnack.error(context, 'No se pudo abrir el turno');
    } finally {
      if (mounted) setState(() => _enviando = false);
    }
  }

  Widget _campo(
    TextEditingController c,
    String label, {
    String? hint,
    TextInputType? keyboard,
    String? Function(String?)? validator,
    int maxLines = 1,
  }) {
    return Padding(
      padding: const EdgeInsets.only(bottom: 12),
      child: TextFormField(
        controller: c,
        style: TextStyle(color: AppColors.text(context)),
        keyboardType: keyboard,
        maxLines: maxLines,
        textCapitalization: keyboard == null
            ? TextCapitalization.sentences
            : TextCapitalization.none,
        decoration: campoTurno(context, label, hint: hint),
        validator: validator,
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final textColor = AppColors.text(context);
    final mutedColor = AppColors.mutedText(context);

    return Scaffold(
      appBar: AppBar(
        title: const Text('Abrir turno de bombeo'),
        backgroundColor: AppColors.surfaceAlt(context),
        foregroundColor: textColor,
        elevation: 0,
      ),
      body: FutureBuilder<BombaPropia?>(
        future: _bombaFuture,
        builder: (context, snapshot) {
          if (snapshot.connectionState != ConnectionState.done) {
            return const Center(child: CircularProgressIndicator());
          }
          final bomba = snapshot.data;

          return Form(
            key: _formKey,
            child: ListView(
              padding: const EdgeInsets.fromLTRB(20, 16, 20, 32),
              children: [
                FieldGroup(
                  expand: true,
                  child: Row(
                    children: [
                      const Icon(
                        Icons.local_shipping_outlined,
                        color: AppColors.accent,
                      ),
                      const SizedBox(width: 10),
                      Expanded(
                        child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            Text(
                              'Bomba',
                              style: TextStyle(fontSize: 12, color: mutedColor),
                            ),
                            Text(
                              bomba == null
                                  ? (snapshot.hasError
                                        ? 'No se pudo consultar tu bomba'
                                        : 'No tienes una bomba asignada')
                                  : (bomba.numeroUnidad?.isNotEmpty == true
                                        ? bomba.numeroUnidad!
                                        : '#${bomba.id}'),
                              style: TextStyle(
                                fontWeight: FontWeight.w700,
                                color: textColor,
                              ),
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                ),
                if (bomba == null) ...[
                  const SizedBox(height: 8),
                  Text(
                    'Pide en planta que te asignen una bomba para poder abrir tu turno.',
                    style: TextStyle(fontSize: 13, color: mutedColor),
                  ),
                ],
                const SizedBox(height: 20),
                _campo(
                  _horometro,
                  'Horómetro de inicio',
                  keyboard: const TextInputType.numberWithOptions(
                    decimal: true,
                  ),
                  validator: validarNumeroOpcional,
                ),
                _campo(_auxiliar, 'Auxiliar (opcional)'),
                const SizedBox(height: 8),
                Text(
                  'Datos del servicio (opcional)',
                  style: TextStyle(
                    fontWeight: FontWeight.w700,
                    color: textColor,
                  ),
                ),
                const SizedBox(height: 10),
                _campo(_cliente, 'Cliente'),
                _campo(_direccion, 'Dirección de la obra'),
                _campo(_entreCalles, 'Entre calles'),
                _campo(_telefono, 'Teléfono', keyboard: TextInputType.phone),
                _campo(_solicitadoPor, 'Solicitado por'),
                _campo(_observaciones, 'Observaciones', maxLines: 3),
                const SizedBox(height: 12),
                SizedBox(
                  width: double.infinity,
                  child: ElevatedButton(
                    onPressed: bomba == null || _enviando
                        ? null
                        : () => _enviar(bomba),
                    style: ElevatedButton.styleFrom(
                      backgroundColor: AppColors.accent,
                      foregroundColor: AppColors.onAccent,
                      disabledBackgroundColor: AppColors.accent.withValues(
                        alpha: 0.3,
                      ),
                      padding: const EdgeInsets.symmetric(vertical: 16),
                      elevation: 0,
                      shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(14),
                      ),
                    ),
                    child: _enviando
                        ? const SizedBox(
                            height: 18,
                            width: 18,
                            child: CircularProgressIndicator(
                              strokeWidth: 2.5,
                              color: Colors.black,
                            ),
                          )
                        : const Text(
                            'Abrir turno',
                            style: TextStyle(fontWeight: FontWeight.w700),
                          ),
                  ),
                ),
              ],
            ),
          );
        },
      ),
    );
  }
}
